import { spawn, type ChildProcess } from "node:child_process";
import { homedir } from "node:os";
import { join } from "node:path";
import {
  createMemoryConfinementLauncher,
  type MemoryConfinementLauncherInput,
  type MemoryConfinementLauncherResult,
} from "@letta-ai/letta-code/memory-confinement";
import { findLettaCli } from "./cli-resolver.js";

export interface LocalAppServerHandle {
  url: string;
  isRunning(): boolean;
  close(): void;
}

export interface StartLocalAppServerOptions {
  listen?: string;
  backend?: string;
  startupTimeoutMs?: number;
  cliPath?: string;
  env?: Record<string, string | undefined>;
  filesystemConfinement?: "memory";
  agentId?: string;
}

interface LocalAppServerProcess {
  command: string;
  args: string[];
  env: NodeJS.ProcessEnv;
}

type MemoryConfinementLauncher = (
  input: MemoryConfinementLauncherInput,
) => MemoryConfinementLauncherResult;

const DEFAULT_LISTEN_URL = "ws://127.0.0.1:0";
const DEFAULT_STARTUP_TIMEOUT_MS = 30_000;
const LISTENING_RE = /^Listening on\s+(ws:\/\/\S+)\s*$/m;

function targetHomeDirectory(env: NodeJS.ProcessEnv): string {
  if (process.platform === "win32") {
    const profile = env.USERPROFILE?.trim();
    if (profile) return profile;
    const drive = env.HOMEDRIVE?.trim();
    const path = env.HOMEPATH?.trim();
    if (drive && path) return `${drive}${path}`;
    return homedir();
  }
  return env.HOME?.trim() || homedir();
}

function withDefaultMemoryDirectory(
  env: NodeJS.ProcessEnv,
  options: StartLocalAppServerOptions,
): NodeJS.ProcessEnv {
  const explicitMemoryDir = options.env?.MEMORY_DIR?.trim();
  const explicitLettaMemoryDir = options.env?.LETTA_MEMORY_DIR?.trim();
  const scopedEnv = { ...env };
  if (explicitMemoryDir || explicitLettaMemoryDir) {
    if (!explicitMemoryDir) delete scopedEnv.MEMORY_DIR;
    if (!explicitLettaMemoryDir) delete scopedEnv.LETTA_MEMORY_DIR;
    return scopedEnv;
  }

  // Never inherit the SDK process's agent scope into a different session.
  delete scopedEnv.MEMORY_DIR;
  delete scopedEnv.LETTA_MEMORY_DIR;
  if (!options.agentId) return scopedEnv;

  const homeDir = targetHomeDirectory(env);
  // Mirrors Letta Code's getScopedMemoryFilesystemRoot contract. The SDK pins
  // an exact Letta Code version so the launch policy and layout move together.
  const memoryDir =
    options.backend === "api"
      ? join(homeDir, ".letta", "agents", options.agentId, "memory")
      : join(
          env.LETTA_LOCAL_BACKEND_DIR?.trim() ||
            join(homeDir, ".letta", "lc-local-backend"),
          "memfs",
          options.agentId,
          "memory",
        );
  return { ...scopedEnv, MEMORY_DIR: memoryDir };
}

function appendLine(buffer: string, chunk: unknown): string {
  return buffer + String(chunk);
}

function tryExtractListeningUrl(output: string): string | null {
  const match = output.match(LISTENING_RE);
  return match?.[1] ?? null;
}

export function buildLocalAppServerArgs(
  cliPath: string,
  options: Pick<StartLocalAppServerOptions, "backend" | "listen"> = {},
): string[] {
  return [
    cliPath,
    ...(options.backend !== undefined ? ["--backend", options.backend] : []),
    "server",
    "--listen",
    options.listen ?? DEFAULT_LISTEN_URL,
  ];
}

export function buildLocalAppServerProcess(
  cliPath: string,
  options: StartLocalAppServerOptions = {},
  confineMemory: MemoryConfinementLauncher = createMemoryConfinementLauncher,
): LocalAppServerProcess {
  const env = { ...process.env, ...(options.env ?? {}) };
  const launcher = [
    process.execPath,
    ...buildLocalAppServerArgs(cliPath, options),
  ];
  const confined =
    options.filesystemConfinement === "memory"
      ? confineMemory({ launcher, env: withDefaultMemoryDirectory(env, options) })
      : { launcher, env };
  // Managed Linux hosts reserve the listener's cgroup for control processes.
  // Apply workload placement even when filesystem confinement is disabled,
  // and outside that confinement so systemd remains accessible at launch.
  const slice = env.LETTA_WORKLOAD_SYSTEMD_SLICE?.trim();
  const managedLauncher =
    process.platform === "linux" && slice
      ? [
          "systemd-run",
          "--scope",
          "--quiet",
          "--collect",
          "--property=TimeoutStopSec=5s",
          `--slice=${slice}`,
          "--",
          ...confined.launcher,
        ]
      : confined.launcher;
  return {
    command: managedLauncher[0] as string,
    args: managedLauncher.slice(1),
    env: confined.env,
  };
}

function terminateProcess(child: ChildProcess): void {
  if (child.exitCode !== null || child.signalCode !== null) return;
  child.kill("SIGTERM");
  setTimeout(() => {
    if (child.exitCode === null && child.signalCode === null) {
      child.kill("SIGKILL");
    }
  }, 1_000).unref?.();
}

/**
 * Spawn an SDK-owned Letta Code app-server on an ephemeral loopback port.
 */
export function startLocalAppServer(
  options: StartLocalAppServerOptions = {},
): Promise<LocalAppServerHandle> {
  const cliPath = options.cliPath ?? findLettaCli();
  const processSpec = buildLocalAppServerProcess(cliPath, options);
  const startupTimeoutMs = options.startupTimeoutMs ?? DEFAULT_STARTUP_TIMEOUT_MS;

  return new Promise((resolve, reject) => {
    const child = spawn(processSpec.command, processSpec.args, {
      stdio: ["ignore", "pipe", "pipe"],
      env: processSpec.env,
    });

    let settled = false;
    let output = "";

    const cleanup = () => {
      child.stdout?.off("data", onStdout);
      child.stderr?.off("data", onStderr);
      child.off("error", onError);
      child.off("exit", onExit);
      clearTimeout(timeout);
    };

    const fail = (error: Error) => {
      if (settled) return;
      settled = true;
      cleanup();
      terminateProcess(child);
      reject(error);
    };

    const succeed = (url: string) => {
      if (settled) return;
      settled = true;
      cleanup();
      resolve({
        url,
        isRunning: () => child.exitCode === null && child.signalCode === null,
        close: () => terminateProcess(child),
      });
    };

    const onOutput = (chunk: unknown) => {
      output = appendLine(output, chunk);
      const url = tryExtractListeningUrl(output);
      if (url) succeed(url);
    };

    const onStdout = (chunk: unknown) => onOutput(chunk);
    const onStderr = (chunk: unknown) => {
      // Startup failures are printed to stderr by the CLI. Keep stderr in the
      // collected output so timeout/exit errors are actionable.
      output = appendLine(output, chunk);
    };
    const onError = (error: Error) => fail(error);
    const onExit = (code: number | null, signal: NodeJS.Signals | null) => {
      if (settled) return;
      fail(
        new Error(
          `Local Letta Code app-server exited before listening (code=${code ?? "null"}, signal=${signal ?? "null"}).${
            output ? ` Output:\n${output.trim()}` : ""
          }`,
        ),
      );
    };

    const timeout = setTimeout(() => {
      fail(
        new Error(
          `Timed out waiting for local Letta Code app-server to start.${
            output ? ` Output:\n${output.trim()}` : ""
          }`,
        ),
      );
    }, startupTimeoutMs);

    child.stdout?.on("data", onStdout);
    child.stderr?.on("data", onStderr);
    child.once("error", onError);
    child.once("exit", onExit);
  });
}
